typedef struct { int key, val; bool used; } HMSlot;
typedef struct { HMSlot *s; size_t cap; } HashMap;
static size_t np2(size_t n){ size_t p=1; while(p<n)p<<=1; return p; }
static size_t hint(int k,size_t c){ uint32_t x=(uint32_t)k; x*=2654435761u; return (size_t)x&(c-1); }
static void hm_init(HashMap*m,size_t e){ m->cap=np2(e<4?4:e*2); m->s=calloc(m->cap,sizeof(HMSlot)); }
static void hm_free(HashMap*m){ free(m->s); }
static bool hm_get(const HashMap*m,int k,int*o){
    size_t i=hint(k,m->cap);
    for(size_t p=0;p<m->cap;p++){ size_t j=(i+p)&(m->cap-1);
        if(!m->s[j].used)return false;
        if(m->s[j].key==k){ if(o)*o=m->s[j].val; return true; } }
    return false; }
static void hm_put(HashMap*m,int k,int v){
    size_t i=hint(k,m->cap);
    for(size_t p=0;p<m->cap;p++){ size_t j=(i+p)&(m->cap-1);
        if(!m->s[j].used){ m->s[j].used=true; m->s[j].key=k; m->s[j].val=v; return; }
        if(m->s[j].key==k){ m->s[j].val=v; return; } } }
bool two_sum(const int *nums,size_t n,int target,int *out_i,int *out_j){
    if(!nums||n<2)return false;
    HashMap m; hm_init(&m,n); bool found=false;
    for(size_t i=0;i<n;i++){
        int idx; if(hm_get(&m,target-nums[i],&idx)){ if(out_i)*out_i=idx; if(out_j)*out_j=(int)i; found=true; break; }
        hm_put(&m,nums[i],(int)i);
    }
    hm_free(&m); return found;
}

typedef struct { int key; bool used; } HSSlot;
typedef struct { HSSlot *s; size_t cap; } HashSet;
static size_t np2(size_t n){ size_t p=1; while(p<n)p<<=1; return p; }
static size_t hint(int k,size_t c){ uint32_t x=(uint32_t)k; x*=2654435761u; return (size_t)x&(c-1); }
static bool hs_add(HashSet*s,int k){
    size_t i=hint(k,s->cap);
    for(size_t p=0;p<s->cap;p++){ size_t j=(i+p)&(s->cap-1);
        if(!s->s[j].used){ s->s[j].used=true; s->s[j].key=k; return false; }
        if(s->s[j].key==k)return true; }
    return false; }
bool contains_duplicate(const int *nums,size_t n){
    if(!nums||n<2)return false;
    HashSet s; s.cap=np2(n<4?4:n*2); s.s=calloc(s.cap,sizeof(HSSlot));
    bool dup=false;
    for(size_t i=0;i<n;i++){ if(hs_add(&s,nums[i])){ dup=true; break; } }
    free(s.s); return dup;
}

void product_except_self(const int *nums,size_t n,long *out){
    if(!nums||!out||n==0)return;
    long prefix=1;
    for(size_t i=0;i<n;i++){ out[i]=prefix; prefix*=nums[i]; }
    long suffix=1;
    for(size_t i=n;i-->0;){ out[i]*=suffix; suffix*=nums[i]; }
}

long range_sum(const int *nums,size_t n,size_t l,size_t r){
    if(!nums||n==0||l>r||r>=n)return 0;
    long *pre=malloc((n+1)*sizeof(long)); if(!pre)return 0;
    pre[0]=0; for(size_t i=0;i<n;i++)pre[i+1]=pre[i]+nums[i];
    long res=pre[r+1]-pre[l]; free(pre); return res;
}

long max_subarray(const int *nums,size_t n){
    if(!nums||n==0)return 0;
    long best=nums[0],cur=nums[0];
    for(size_t i=1;i<n;i++){ long v=nums[i]; cur=(v>cur+v)?v:cur+v; if(cur>best)best=cur; }
    return best;
}

long max_sum_window_k(const int *nums,size_t n,size_t k){
    if(!nums||k==0||k>n)return 0;
    long sum=0; for(size_t i=0;i<k;i++)sum+=nums[i];
    long best=sum;
    for(size_t i=k;i<n;i++){ sum+=nums[i]-nums[i-k]; if(sum>best)best=sum; }
    return best;
}

bool pair_sum_sorted(const int *nums,size_t n,int target,int *out_i,int *out_j){
    if(!nums||n<2)return false;
    size_t lo=0,hi=n-1;
    while(lo<hi){ long s=(long)nums[lo]+nums[hi];
        if(s==target){ if(out_i)*out_i=(int)lo; if(out_j)*out_j=(int)hi; return true; }
        if(s<target)lo++; else hi--; }
    return false;
}

void move_zeroes(int *nums,size_t n){
    if(!nums||n==0)return;
    size_t w=0;
    for(size_t i=0;i<n;i++) if(nums[i]!=0) nums[w++]=nums[i];
    while(w<n) nums[w++]=0;
}

int majority_element(const int *nums,size_t n){
    int cand=0,count=0;
    for(size_t i=0;i<n;i++){ if(count==0)cand=nums[i]; count+=(nums[i]==cand)?1:-1; }
    return cand;
}

