typedef struct { int val, freq; } VF;
static int vf_cmp(const void *a,const void *b){
    const VF *x=a,*y=b; if(x->freq!=y->freq)return y->freq-x->freq; return x->val-y->val; }
void top_k_frequent(const int *nums,size_t n,size_t k,int *out){
    if(!nums||!out||k==0||n==0)return;
    HashMap m; hm_init(&m,n); VF *u=malloc(n*sizeof(VF)); size_t un=0;
    for(size_t i=0;i<n;i++){ int c;
        if(hm_get(&m,nums[i],&c))hm_put(&m,nums[i],c+1);
        else { hm_put(&m,nums[i],1); u[un++].val=nums[i]; } }
    for(size_t i=0;i<un;i++){ int c; hm_get(&m,u[i].val,&c); u[i].freq=c; }
    qsort(u,un,sizeof(VF),vf_cmp);
    size_t take=(k<un)?k:un;
    for(size_t i=0;i<take;i++)out[i]=u[i].val;
    free(u); hm_free(&m);
}
